 const targets:ImportTarget[]=['outline','theme','style','world','character','scene','item','foreshadow','goldenFinger','trope','worldline','narrative'],rawWorldSource='世界观\n完整未结构化原资料首句。\n原资料末句。';const h=await fixture(async r=>{if(r.intent==='reconcile')return proposal(r);if(r.phase==='analyze')return r.kind==='world'?{artifacts:[make(r.units[0],'derived-world','world',{entityType:'WORLD'},'')]}:outlineResult(r);return {conflicts:[]}},[{name:'正文.txt',text:body},{name:'世界观.txt',text:rawWorldSource}]);try{await h.ready(true,targets);await h.act('start',{consent:true});assert.equal((await h.settle()).phase,'completed');const s=await h.saved(),source=s.artifacts.find(a=>a.kind==='world'&&a.origin==='source')!;assert.equal(source.text,rawWorldSource);assert.deepEqual(source.facts,{});assert.ok(s.artifacts.some(a=>a.id==='derived-world'&&a.origin==='inferred'&&a.facts.entityType==='WORLD'));assert.deepEqual([...new Set(h.requests.filter(r=>r.phase==='analyze'&&!r.intent).map(r=>r.kind))].sort(),[...targets].sort());for(const r of h.requests)for(const entity of r.entities??[])if(entity.id===source.id)assert.equal(entity.entityType,undefined,'raw source is never disguised as WORLD');assert.ok(h.requests.filter(r=>r.phase==='review').flatMap(r=>r.units).some(u=>u.text.includes('原资料末句')));assert.equal(h.published[0].session.artifacts.find(a=>a.id===source.id)!.text,rawWorldSource)}finally{await h.dispose()}

