// RB08/RB15: the real adapter rebinds a verbatim-unique quote to its single
// owning unit inside ordinary analysis and omission completion; prose unchanged.
const owned=(units:ImportUnit[],declared:ImportUnit)=>{const pool=units.filter(u=>u.id!==declared.id);for(const u of pool){for(let n=Math.min(24,u.text.length);n>=8;n--){const quote=u.text.slice(0,n).trim();if([...quote].filter(c=>!/\s/u.test(c)).length<8||declared.text.includes(quote))continue;const hits=units.reduce((sum,unit)=>{let k=0;for(let p=unit.text.indexOf(quote);p!==-1;p=unit.text.indexOf(quote,p+1))k++;return sum+k},0);if(hits===1)return {owner:u,quote}}}return undefined}
test('RB08: ordinary analysis commits a rebound evidence entry without bisection',async()=>{
 let pair:{owner:ImportUnit;quote:string}|undefined,declared:ImportUnit|undefined
 const f=await fixture(async r=>{if(r.phase==='analyze'&&!r.intent&&!pair){declared=r.units[0];pair=owned(r.units,declared);assert.ok(pair,'synthetic batch has a second unit with a unique quote');const a=person(declared);a.evidence=[{unitId:declared.id,quote:pair.quote}];return {artifacts:[a]}}if(r.intent==='reconcile')return {artifactEdits:[],conflicts:[]};return r.phase==='analyze'?{notFound:true}:{conflicts:[]}})
 f.useAdapter()
 try{await f.ready();await f.act('start',{consent:true});assert.equal((await f.settle()).phase,'completed');const s=await f.saved(),a=s.artifacts.find(a=>a.id==='person-a')!
  assert.deepEqual(a.evidence,[{unitId:pair!.owner.id,quote:pair!.quote}]);assert.deepEqual(a.sourceUnitIds,[declared!.id,pair!.owner.id]);assert.equal(f.requests.filter(r=>r.phase==='analyze'&&!r.intent&&r.kind==='character').length,1,'no correction or bisection');assert.equal(s.workingProse,s.originalProse)
 }finally{await f.dispose()}
})
test('RB15: omission completion accepts the same rebind',async()=>{
 let issued=false,pair:{owner:ImportUnit;quote:string}|undefined,declared:ImportUnit|undefined
 const f=await fixture(async r=>{
  if(r.intent==='reconcile')return {artifactEdits:[],conflicts:[]}
  if(r.phase==='analyze'){if(!issued)return {artifacts:[person(r.units[0])]};declared=r.units[0];pair=owned(r.units,declared);assert.ok(pair,'omission request spans two units');const a=person(declared,'new-only');a.evidence=[{unitId:declared.id,quote:pair.quote}];return {artifacts:[a]}}
  if(!issued){const us=r.units.filter(u=>[...u.text].filter(c=>!/\s/u.test(c)).length>=8).slice(0,2);assert.equal(us.length,2);issued=true;return {conflicts:[],missingTargets:[{kind:'character',unitIds:us.map(u=>u.id),evidence:us.flatMap(evidence),reason:'合成新实体跨两个单元'}]} as any}
  return {conflicts:[]}
 },[{name:'正文.txt',text:body},{name:'世界观.txt',text:'世界观\n合成遗漏证据首段甲乙丙丁。\n\n合成遗漏证据末段戊己庚辛。'}])
 f.useAdapter()
 try{await f.ready();await f.act('start',{consent:true});assert.equal((await f.settle()).phase,'completed');const s=await f.saved(),a=s.artifacts.find(a=>a.id==='new-only')!
  assert.ok(a,'omission entity committed');assert.deepEqual(a.evidence,[{unitId:pair!.owner.id,quote:pair!.quote}]);assert.ok(a.sourceUnitIds.includes(declared!.id)&&a.sourceUnitIds.includes(pair!.owner.id));assert.ok(s.semanticState!.omissions.every(o=>o.done))
 }finally{await f.dispose()}
})

