test('MG12a: omission completion keeps an author-locked occupation as a conflict',async()=>{
 let reported=false,decided=false,missing=false
 const f=await fixture(async r=>{
  if(r.intent==='reconcile')return {artifactEdits:[],conflicts:[]}
  if(r.phase==='analyze'){if(!missing)return {artifacts:[person(r.units[0])]};const a=person(r.units[0],'omission-new');a.name='合成角色甲';a.facts.roleType='PROTAGONIST';a.facts.relationships='[]';a.facts.occupation='后期新职业';return {artifacts:[a]}}
  if(!reported){reported=true;return {conflicts:[castConflict(person(r.units[0]),r.units[0])]}}
  if(decided&&!missing){const u=r.units.find(u=>u.kind==='world');if(u){missing=true;return {conflicts:[],missingTargets:[{kind:'character',unitIds:[u.id],evidence:evidence(u),reason:'合成遗漏'}]}}}
  return {conflicts:[]}
 },[{name:'正文.txt',text:body},{name:'世界观.txt',text:'世界观\n完全不同的原资料证据。'}])
 f.useAdapter()
 try{await f.ready();await f.act('start',{consent:true});assert.equal((await f.settle()).phase,'conflicts');const before=await f.saved();decided=true
  await f.act('resolve',{conflictId:before.conflicts[0].id,choice:'source',explanation:'作者确认职业。'})
  const view=await f.settle(),s=await f.saved();assert.equal(view.phase,'conflicts',String(s.error));assert.equal(s.artifacts.find(a=>a.id==='person-a')!.facts.occupation,'早期整理资料')
  assert.ok(s.conflicts.some(c=>c.status==='pending'&&c.field==='occupation'))
 }finally{await f.dispose()}
})
